+        else return ((RSAPrivateKey) key).getModulus().bitLength();
+    }
+
+    private static byte[] concatArrays(byte[] a, byte[] b) {
+        int aLen = a.length;
+        int bLen = b.length;
+        byte[] result = new byte[aLen + bLen];
+        System.arraycopy(a, 0, result, 0, aLen);
+        System.arraycopy(b, 0, result, aLen, bLen);
+        return result;
+    }
