+    public String configUrl(String apiUrl){
+        TempKey = null;
+        String configUrl = "", pk = ";pk;";
+        // 正确解析file://协议：处理三斜杠file:///和绝对路径重复问题
+        if (apiUrl.startsWith("file://")) {
+            String filePath = apiUrl.substring(7); // 去掉"file://"
+            // 修复：必须先判断绝对路径再剥前导斜杠——storageRoot以"/"开头，
+            // 先剥斜杠则startsWith永远为假，绝对路径转换成为死代码，
+            // file:///storage/...会被拼成/storage/emulated/0/storage/emulated/0/...而500
+            String storageRoot = Environment.getExternalStorageDirectory().getAbsolutePath();
+            String absPath = filePath.startsWith("/") ? filePath : "/" + filePath;
+            if (absPath.startsWith(storageRoot)) {
+                filePath = absPath.substring(storageRoot.length());
+            }
+            if (filePath.startsWith("/")) {
+                filePath = filePath.substring(1); // 去掉开头的/
+            }
+            apiUrl = "clan://localhost/" + filePath;
+        } else {
+            apiUrl=apiUrl.replace("file://", "clan://localhost/");
+        }
+        if (apiUrl.contains(pk)) {
+            String[] a = apiUrl.split(pk);
+            TempKey = a[1];
+            if (apiUrl.startsWith("clan://")){
+                configUrl = clanToAddress(a[0]);
+            }else if (apiUrl.startsWith("http")){
+                configUrl = a[0];
+            }else {
+                configUrl = "http://" + a[0];
+            }
+        } else if (apiUrl.startsWith("clan://")) {
+            configUrl = clanToAddress(apiUrl);
+        } else if (!apiUrl.startsWith("http")) {
+            configUrl = "http://" + apiUrl;
+        } else {
+            configUrl = apiUrl;
+        }
+        return configUrl;
+    }
