+    private void loadConfigInternal(boolean useCache, LoadConfigCallback callback, Activity activity,
+                                    final int depth, final Set<String> visited) {
+        String apiUrl = Hawk.get(HawkConfig.API_URL, "");
+        if (apiUrl.isEmpty()) {
+            callback.error("-1");
+            return;
+        }
+        final File cache = new File(App.getInstance().getFilesDir().getAbsolutePath() + "/" + MD5.encode(apiUrl));
+        if (useCache && cache.exists()) {
+            // 缓存解析放到后台线程，首页先出画面，不被大 JSON + Hawk 写入卡住
+            configLoadExecutor.execute(new Runnable() {
+                @Override
+                public void run() {
+                    try {
+                        String json = readConfigFile(cache);
+                        if (switchApiCollectionIfNeeded(apiUrl, json)) {
+                            continueAfterSwitch(apiUrl, json, cache, false, depth, visited, callback, activity);
+                            return;
+                        }
+                        clearApiLinesIfUnmatched(apiUrl);
+                        parseJson(apiUrl, json);
+                        mainHandler.post(new Runnable() {
+                            @Override
+                            public void run() {
+                                callback.success();
+                            }
+                        });
+                    } catch (Throwable th) {
+                        th.printStackTrace();
+                        mainHandler.post(new Runnable() {
+                            @Override
+                            public void run() {
+                                callback.error("配置缓存解析失败");
+                            }
+                        });
+                    }
+                }
+            });
+            return;
+        }
+        // configUrl()写TempKey、读TempKey必须原子执行：TempKey是单例字段，
+        // 对话框后台线程（ConfigFetcher.resolve）会并发写，两步分开会被覆盖导致AES解出乱码。
+        // 锁用本单例实例，与ConfigFetcher.resolve同锁
+        String configUrl;
+        final String configKey;
+        synchronized (this) {
+            configUrl = configUrl(apiUrl);
+            configKey = TempKey;
+        }
+
+        fetchConfigAsync(apiUrl, configUrl, configKey, new ConfigFetchCallback() {
+            @Override
+            public void success(String json) {
+                try {
+                    if (switchApiCollectionIfNeeded(apiUrl, json)) {
+                        continueAfterSwitch(apiUrl, json, cache, true, depth, visited, callback, activity);
+                        return;
+                    }
+                    clearApiLinesIfUnmatched(apiUrl);
+                    parseJson(apiUrl, json);
+                    FileUtils.saveCache(cache, json);
+                    mainHandler.post(new Runnable() {
+                        @Override
+                        public void run() {
+                            callback.success();
+                        }
+                    });
+                } catch (Throwable th) {
+                    th.printStackTrace();
+                    mainHandler.post(new Runnable() {
+                        @Override
+                        public void run() {
+                            callback.error("配置解析失败");
+                        }
+                    });
+                }
+            }
+
+            @Override
+            public void error(String error) {
+                if (cache.exists()) {
+                    try {
+                        String json = readConfigFile(cache);
+                        if (switchApiCollectionIfNeeded(apiUrl, json)) {
+                            continueAfterSwitch(apiUrl, json, cache, false, depth, visited, callback, activity);
+                            return;
+                        }
+                        clearApiLinesIfUnmatched(apiUrl);
+                        parseJson(apiUrl, json);
+                        mainHandler.post(new Runnable() {
+                            @Override
+                            public void run() {
+                                callback.success();
+                            }
+                        });
+                        return;
+                    } catch (Throwable th) {
+                        th.printStackTrace();
+                    }
+                }
+                final String finalError = error;
+                mainHandler.post(new Runnable() {
+                    @Override
+                    public void run() {
+                        callback.error("拉取配置失败\n" + finalError);
+                    }
+                });
+            }
+        }, false);
+    }
+
+    /**
+     * switchApiCollectionIfNeeded 切换成功后的统一出口（三处调用点：缓存命中/网络成功/网络失败回退缓存）。
+     * C1断环：visited 命中下一跳或深度超过 5 层时不再自动切换，把当前 json 当普通配置解析——
+     * urls 线路集合没有 sites 段，parseJson 内部已对 sites 判空兜底，
+     * 最坏结果是站点列表为空，而不是 A→B→A 无限递归重载或 NPE 闪退。
+     */
+    private void continueAfterSwitch(String apiUrl, String json, File cache, boolean saveCache,
+                                     int depth, Set<String> visited,
+                                     LoadConfigCallback callback, Activity activity) throws Throwable {
+        visited.add(apiUrl);
+        String nextApi = Hawk.get(HawkConfig.API_URL, "");
+        boolean loop = depth >= 5 || nextApi.isEmpty() || visited.contains(nextApi);
+        if (saveCache) {
+            FileUtils.saveCache(cache, json);
+        }
+        if (loop) {
+            clearApiLinesIfUnmatched(apiUrl);
+            parseJson(apiUrl, json);
+            mainHandler.post(new Runnable() {
+                @Override
+                public void run() {
+                    callback.success();
+                }
+            });
+        } else {
+            loadConfigInternal(false, callback, activity, depth + 1, visited);
+        }
+    }
