+    private void fetchConfigAsync(final String apiUrl, final String requestUrl, final String configKey,
+                                  final ConfigFetchCallback callback, final boolean callbackOnMainThread) {
+        configLoadExecutor.execute(new Runnable() {
+            @Override
+            public void run() {
+                String result = "";
+                String error = "";
+                okhttp3.Response response = null;
+                try {
+                    // 与三个对话框的抓取栈（ConfigFetcher）对齐：
+                    // 中文等非ASCII路径百分号编码 + UA（gitcode特殊UA，其余Mozilla/5.0）
+                    String safeUrl = ConfigFetcher.encodeUnsafeUrlChars(requestUrl);
+                    okhttp3.Request.Builder requestBuilder = new okhttp3.Request.Builder()
+                            .url(safeUrl);
+                    if (safeUrl.startsWith("https://gitcode")) {
+                        requestBuilder.header("User-Agent",
+                                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
+                        requestBuilder.header("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8");
+                    } else {
+                        requestBuilder.header("User-Agent", "Mozilla/5.0");
+                    }
+                    okhttp3.Request request = requestBuilder.build();
+                    okhttp3.OkHttpClient client = OkGoHelper.getDefaultClient();
+                    if (client == null) client = com.github.catvod.net.OkHttp.client();
+                    response = client.newCall(request).execute();
+                    if (!response.isSuccessful()) {
+                        error = "HTTP " + response.code();
+                    } else if (response.body() == null) {
+                        error = "empty body";
+                    } else {
+                        result = FindResult(response.body().string(), configKey);
+                        if (apiUrl.startsWith("clan://") || apiUrl.startsWith("file://")) {
+                            result = clanContentFix(requestUrl, result);
+                        }
+                        result = fixContentPath(apiUrl, result);
+                    }
+                } catch (Throwable th) {
+                    error = th.getMessage();
+                    if (TextUtils.isEmpty(error)) error = th.toString();
+                } finally {
+                    if (response != null) closeQuietly(response.body());
+                }
+                final String finalResult = result;
+                final String finalError = error;
+                Runnable deliver = new Runnable() {
+                    @Override
+                    public void run() {
+                        if (TextUtils.isEmpty(finalError)) {
+                            callback.success(finalResult);
+                        } else {
+                            callback.error(finalError);
+                        }
+                    }
+                };
+                if (callbackOnMainThread) {
+                    mainHandler.post(deliver);
+                } else {
+                    deliver.run();
+                }
+            }
+        });
+    }
