+    /**
+     * 把配置里的 spider / 站点 jar 地址规整成可下载的绝对地址，同时支持两种写法：
+     *   1) 远程在线绝对地址：http(s)://、file://、clan://、assets、content:// —— 原样返回，零影响
+     *   2) 相对路径：./xxx.jar、../xxx.jar、xxx.jar —— 以「配置地址所在目录」为基准解析成绝对地址
+     *
+     * 旧实现只在网络拉配置时靠 fixContentPath 对整份 JSON 做字符串替换（且要求引号紧贴 ./），
+     * 配置从磁盘缓存加载（loadConfigInternal -> parseJson(apiUrl, json)）完全不走该替换，
+     * 相对地址会原样落到 downloadJarAsync 的 .url("./xxx.jar")，OkHttp 判非法 URL，
+     * 下载失败后回落加载 csp 缓存 -> 报「md5缓存失效 / jar load err」。
+     * 这里在解析层做确定性规整，覆盖网络 / 缓存 / 本地文件 / 对话框导入全部来源。
+     * 保留 ;md5; 校验段与 img+ 前缀。
+     */
+    private String resolveSpiderUrl(String apiUrl, String spider) {
+        if (TextUtils.isEmpty(spider)) return spider;
+        String[] parts = spider.split(";md5;", 2);
+        String path = parts[0];
+        String md5 = parts.length > 1 ? ";md5;" + parts[1] : "";
+        String prefix = "";
+        if (path.startsWith("img+")) {
+            prefix = "img+";
+            path = path.substring(4);
+        }
+        // 绝对地址 / 特殊 scheme 原样返回：远程在线路径不受影响
+        if (path.startsWith("http://") || path.startsWith("https://")
+                || path.startsWith("file://") || path.startsWith("clan://")
+                || path.startsWith("assets") || path.startsWith("content://")
+                || path.startsWith("/")) {
+            return spider;
+        }
+        if (TextUtils.isEmpty(apiUrl)) return spider;
+        // 与 fixContentPath / clanContentFix 一致的基址规范化
+        String base = apiUrl;
+        if (base.startsWith("file://")) base = "clan://localhost/" + base.substring(7);
+        if (!base.startsWith("http") && !base.startsWith("clan://")) base = "http://" + base;
+        if (base.startsWith("clan://")) {
+            try {
+                base = clanToAddress(base);
+            } catch (Throwable ignored) {
+                return spider;
+            }
+        }
+        try {
+            String resolved = UriUtil.resolve(base, path);
+            if (TextUtils.isEmpty(resolved) || !resolved.startsWith("http")) return spider;
+            String result = prefix + resolved + md5;
+            LOG.i("echo-resolve spider: " + spider + " -> " + result);
+            return result;
+        } catch (Throwable th) {
+            return spider;
+        }
+    }
