+            if (filterSelect == null) {
+                return 0;
+            }
+            int count = 0;
+            for (String filter : filterSelect.values()) {
+                if (filter != null && !filter.isEmpty()) {
+                    count++;
+                }
+            }
+            return count;
+        }
