+                    "id='" + id + '\'' +
+                    ", name='" + name + '\'' +
+                    ", sort=" + sort +
+                    ", select=" + select +
+                    ", filters=" + filters +
+                    ", filterSelect=" + filterSelect +
+                    ", flag='" + flag + '\'' +
+                    '}';
+        }
+    }
+
+    public static class SortFilter {
+        public String key;
+        public String name;
+        public LinkedHashMap<String, String> values;
+
+        @Override
+        public String toString() {
