+public class VodInfo implements Serializable {
+    public String last;//时间
+    //内容id
+    public String id;
+    //父级id
+    public int tid;
+    //影片名称 <![CDATA[老爸当家]]>
+    public String name;
+    //类型名称
+    public String type;
+    //视频分类zuidam3u8,zuidall
+    public String dt;
