+    @Override
+    public boolean onKeyEvent(KeyEvent event) {
+        myHandle.removeCallbacks(myRunnable);
+        if (super.onKeyEvent(event)) {
+            return true;
+        }
+        int keyCode = event.getKeyCode();
+        int action = event.getAction();
+        if (action == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0 && keyCode == KeyEvent.KEYCODE_MENU) {
+            //选集入口已移到控制条「选集」按钮，菜单键改为呼出控制条，不再直接弹选集
+            if (isBottomVisible()) hideBottom();
+            else showBottom();
+            return true;
+        }
+        if (isBottomVisible()) {
+            mHandler.removeMessages(1002);
+            mHandler.removeMessages(1003);
+            myHandle.postDelayed(myRunnable, myHandleSeconds);
+            return super.dispatchKeyEvent(event);
+        }
+        if (action == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0
+                && videoPlayState == VideoView.STATE_ERROR
+                && (keyCode == KeyEvent.KEYCODE_DPAD_UP
+                || keyCode == KeyEvent.KEYCODE_DPAD_DOWN
+                || keyCode == KeyEvent.KEYCODE_DPAD_LEFT
+                || keyCode == KeyEvent.KEYCODE_DPAD_RIGHT
+                || keyCode == KeyEvent.KEYCODE_DPAD_CENTER
+                || keyCode == KeyEvent.KEYCODE_ENTER
+                || keyCode == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE)) {
+            showBottom();
+            myHandle.postDelayed(myRunnable, myHandleSeconds);
+            return true;
+        }
+        boolean isInPlayback = isInPlaybackState();
+        if (action == KeyEvent.ACTION_DOWN) {
+            if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT || keyCode == KeyEvent.KEYCODE_DPAD_LEFT) {
+                if (isInPlayback) {
+                    tvSlideStart(keyCode == KeyEvent.KEYCODE_DPAD_RIGHT ? 1 : -1);
+                    return true;
+                }
+            } else if (keyCode == KeyEvent.KEYCODE_DPAD_CENTER || keyCode == KeyEvent.KEYCODE_ENTER || keyCode == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE) {
+                if (isInPlayback) {
+                    if (event.getRepeatCount() == 0) togglePlay();
+                    return true;
+                }
+            } else if (keyCode == KeyEvent.KEYCODE_DPAD_DOWN) {
+                if (!isBottomVisible()) {
+                    showBottom();
+                    myHandle.postDelayed(myRunnable, myHandleSeconds);
+                    return true;
+                }
+            }
+        } else if (action == KeyEvent.ACTION_UP) {
+            if (keyCode == KeyEvent.KEYCODE_DPAD_RIGHT || keyCode == KeyEvent.KEYCODE_DPAD_LEFT) {
+                if (isInPlayback) {
+                    tvSlideStop();
+                    return true;
+                }
+            }
+        }
+        return super.dispatchKeyEvent(event);
+    }
